// +page.server.ts  (src/routes/+page.server.ts)
import { fail, redirect } from '@sveltejs/kit';

export const actions = {
	default: async ({ request, url }) => {
		const data = await request.formData();
		const email = (data.get('email') ?? '').toString().trim();
		const password = (data.get('password') ?? '').toString();

		// validation (server-side; fails return status + data for form reuse)
		if (!email) {
			return fail(400, { email, missing: true });
		}
		if (password.length < 6) {
			return fail(422, { email, error: 'Password too short' });
		}
		// (example: pretend DB success or auth fail)
		// if invalid creds: return fail(400, { email, incorrect: true });

		// success: redirect (prevents re-POST on reload; uses 303 per docs)
		if (url.searchParams.has('redirectTo')) {
			redirect(303, url.searchParams.get('redirectTo')!);
		}
		redirect(303, '/success');  // or return { success: true } for in-page message
	}
};
```

